/* @lc app=leetcode id=4068 lang=kotlin */ class Solution { fun maxEarnings(meetings: Array<IntArray>): Long = meetings.sortedBy { it[1] }.fold(Triple(ArrayList<Long>(), ArrayList<Long>(), Long.MIN_VALUE)) { (ends, pm, best), m -> (-(ends.binarySearch { if (it <= m[0]) -1 else 1 }) - 1).let { ins -> (m[2] + (if (ins == 0) 0L else maxOf(0L, pm[ins - 1] + m[0]))).let { f -> ends.add(m[1].toLong()).let { pm.add(maxOf(pm.lastOrNull() ?: (Long.MIN_VALUE / 4), f - m[1])).let { Triple(ends, pm, maxOf(best, f)) } } } } }.third }